{
  "query": "phishing email delivery",
  "top_techniques": [
    {
      "mitre_id": "T1566",
      "name": "Phishing",
      "rationale": "This is the parent technique for sending electronically delivered social engineering messages, including emails, to gain access to victim systems. The user's query directly describes this activity. Phishing can be targeted (spearphishing) or non-targeted, and can contain malicious links or attachments.",
      "citations": [
        "S1",
        "S2",
        "S3"
      ]
    },
    {
      "mitre_id": "T1566.002",
      "name": "Spearphishing Link",
      "rationale": "This technique describes a specific method of phishing where an adversary sends a targeted email containing a malicious link. The goal is to have the user click the link to download malware or be compromised, which is a common payload for a phishing email.",
      "citations": [
        "S4",
        "S5",
        "S6"
      ]
    },
    {
      "mitre_id": "T1566.001",
      "name": "Spearphishing Attachment",
      "rationale": "This technique describes a specific method of phishing where an adversary sends a targeted email with a malicious file attached. The user is tricked into opening the attachment, which then executes a payload on their system. This is another primary method for phishing email delivery.",
      "citations": [
        "S10",
        "S11",
        "S12"
      ]
    }
  ],
  "summary": "The user's query describes the delivery of phishing emails, a common method for initial access. The primary technique is T1566 (Phishing), which involves sending malicious emails to gain system access. This is typically accomplished by embedding a malicious link (T1566.002) or including a malicious attachment (T1566.001). To facilitate the delivery, adversaries may first acquire infrastructure by compromising existing email accounts (T1586.002) or creating new ones (T1585.002).",
  "alternatives": [
    {
      "mitre_id": "T1586.002",
      "name": "Email Accounts",
      "rationale": "This technique, under the tactic 'Compromise Infrastructure', describes how adversaries compromise existing email accounts to send phishing messages. Using a legitimate, compromised account increases the trustworthiness and success rate of the phishing attempt.",
      "citations": [
        "S7",
        "S8",
        "S9"
      ]
    },
    {
      "mitre_id": "T1585.002",
      "name": "Email Accounts",
      "rationale": "This technique, under the tactic 'Establish Accounts', describes how adversaries create new email accounts to be used for phishing campaigns. This is a necessary preparatory step for delivering phishing emails from an adversary-controlled source.",
      "citations": [
        "S19",
        "S20",
t        "S21"
      ]
    },
    {
      "mitre_id": "T1598",
      "name": "Phishing for Information",
      "rationale": "This technique is closely related to the user's query but has a different objective. While standard phishing (T1566) aims to execute code, this technique's goal is to trick victims into divulging sensitive information, such as credentials, rather than gaining system access.",
      "citations": [
        "S22",
        "S23",
        "S24"
      ]
    },
    {
      "mitre_id": "T1566.003",
      "name": "Spearphishing via Service",
      "rationale": "This is an alternative delivery method for phishing that does not use traditional enterprise email. Instead, it leverages third-party services like social media or personal webmail to send the malicious messages.",
      "citations": [
        "S13",
        "S14",
        "S15"
      ]
    }
  ]
}
